// Update changes a subscription's plan or quantity. A subscription's value is its plan's unit amount times its quantity:
//   - An upgrade (the value rises) applies at once and is billed at once for the time left in the current period (prorate).
//   - A downgrade (the value falls) is pending: it takes effect at the next renewal, which bills it.
//   - Any other change applies at once and bills nothing. So does any change to a trialing subscription.
//
// A change to a different plan needs plans of the same currency and interval, and neither may be metered.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	cur, ok := s.Store.Subscription(orgID, id)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if cur.Status == store.Canceled {
		return store.Subscription{}, ErrCanceled
	}
	from, ok := s.Store.Plan(orgID, cur.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	to := from
	if in.PlanID != nil {
		if to, ok = s.Store.Plan(orgID, *in.PlanID); !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !to.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	if from.Currency != to.Currency || from.Interval != to.Interval || from.UsageType != store.Licensed || to.UsageType != store.Licensed {
		return store.Subscription{}, ErrIncompatiblePlan
	}
	qty := cur.Quantity
	if in.Quantity != nil {
		qty = *in.Quantity
	}
	oldValue, newValue := from.UnitAmount*int64(cur.Quantity), to.UnitAmount*int64(qty)
	billed := cur.Status != store.Trialing
	upgrade := billed && newValue > oldValue
	downgrade := billed && newValue < oldValue

	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		if downgrade {
			planID, q := to.ID, qty
			sub.PendingPlanID, sub.PendingQuantity = &planID, &q
			return nil
		}
		sub.PlanID, sub.Quantity = to.ID, qty
		sub.PendingPlanID, sub.PendingQuantity = nil, nil
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	if !upgrade {
		return sub, nil
	}
	paid, err := s.prorate(ctx, sub, from, to, oldValue, newValue)
	if err != nil {
		return sub, err
	}
	if !paid {
		return s.setStatus(ctx, sub, store.PastDue)
	}
	return sub, nil
}

// prorate bills an upgrade for the time left in the current period. The invoice credits the unused time on the old plan and
// charges the remaining time on the new plan, each the share of the period that is left, rounded to a whole minor unit. It is
// charged like any invoice and reports false when the charge was declined.
func (s *Service) prorate(ctx context.Context, sub store.Subscription, from, to store.Plan, fromValue, toValue int64) (bool, error) {
	now := s.Clock.Now()
	length := int64(sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / time.Second)
	remaining := min(max(int64(sub.CurrentPeriodEnd.Sub(now)/time.Second), 0), length)
	lines := []store.Line{
		{Description: "Unused time on " + from.Name, Quantity: 1, UnitAmount: -money.Prorate(fromValue, remaining, length)},
		{Description: "Remaining time on " + to.Name, Quantity: 1, UnitAmount: money.Prorate(toValue, remaining, length)},
	}
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: to.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent}, now)
	if err != nil {
		return false, err
	}
	return s.charge(ctx, sub, inv)
}

