		t.Fatalf("proration invoice = %+v", invs.Items)
	}

	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": team.ID}, &sub)
	if sub.PlanID != pro.ID || sub.PendingPlanID == nil || *sub.PendingPlanID != team.ID || sub.PendingQuantity != nil {
		t.Fatalf("downgrade = %+v", sub)
	}
	if m := e.Do("GET", "/v1/subscriptions/"+sub.ID, e.Acme.Key, nil).Map(t); m["pending_plan_id"] != team.ID || m["pending_quantity"] != nil {
		t.Fatalf("pending fields = %v", m)
	}
}

