// subscribe starts a subscription for c to p.
func subscribe(t *testing.T, e *apitest.Env, c store.Customer, p store.Plan, qty int) store.Subscription {
	t.Helper()
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: qty})
	if err != nil {
		t.Fatal(err)
	}
	return sub
}

// invoicesOf returns the invoices of sub, oldest first.
func invoicesOf(e *apitest.Env, sub store.Subscription) []store.Invoice {
