179	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
180		now := s.Clock.Now()
181		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
182			if sub.Status == store.Canceled {
183				return nil
184			}
185			if atPeriodEnd {
186				sub.CancelAtPeriodEnd = true
187				return nil
188			}
189			sub.Status, sub.CanceledAt = store.Canceled, &now
190			return nil
191		})
192		if err != nil {
193			return store.Subscription{}, err
194		}
195		if sub.Status == store.Canceled {
196			s.publish(ctx, orgID, "subscription.canceled", sub)
197		} else {
198			s.publish(ctx, orgID, "subscription.updated", sub)
199		}
200		return sub, nil
201	}
202	
203	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
204	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
205	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
206	// due. RenewDue returns how many subscriptions it renewed or canceled.
207	func (s *Service) RenewDue(ctx context.Context) (int, error) {
208		now := s.Clock.Now()
209		n := 0
210		for _, sub := range s.Store.DueSubscriptions(now) {
211			if err := ctx.Err(); err != nil {
212				return n, err
213			}
214			if err := s.renew(ctx, sub, now); err != nil {
215				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
216			}
217			n++
218		}
219		return n, nil
220	}
221	
222	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
223		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
224		if !ok {
225			return store.ErrNotFound
226		}
227		if sub.CancelAtPeriodEnd {
228			end := sub.CurrentPeriodEnd
229			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
230				x.Status, x.CanceledAt = store.Canceled, &end
231				return nil
232			})
233			if err == nil {
234				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
235			}
236			return err
237		}
238		// A pending downgrade takes effect now, and the new period is billed for the new plan and quantity.
239		pending := sub.PendingPlanID != nil || sub.PendingQuantity != nil
240		if sub.PendingPlanID != nil {
241			if plan, ok = s.Store.Plan(sub.OrgID, *sub.PendingPlanID); !ok {
242				return store.ErrNotFound
243			}
244			sub.PlanID = plan.ID
245		}
246		if sub.PendingQuantity != nil {
247			sub.Quantity = *sub.PendingQuantity
248		}
249		start := now
250		end := billing.AddInterval(start, plan.Interval)
251		paid := true
252		var err error
253		switch {
254		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
255			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
256		case plan.UsageType == store.Licensed:
257			paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
258		}
259		if err != nil {
260			return err
261		}
262		planID, qty := sub.PlanID, sub.Quantity
263		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
264			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
265			if pending {
266				x.PlanID, x.Quantity = planID, qty
267				x.PendingPlanID, x.PendingQuantity = nil, nil
268			}
269			if paid {
270				x.Status = store.Active
271			} else {
272				x.Status = store.PastDue
273			}
274			return nil
275		})
276		if err != nil {
277			return err
278		}
279		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
280		return nil
281	}
282	
283	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
284	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
